package com.healthwise.report.controller;import com.healthwise.report.dto.ReportDtos.*;import com.healthwise.report.service.ReportService;import com.healthwise.security.CurrentUser;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/reports")public class ReportController{private final ReportService s;public ReportController(ReportService x){s=x;}@PostMapping@ResponseStatus(HttpStatus.CREATED)public Response save(@AuthenticationPrincipal CurrentUser u,@Valid@RequestBody Create d){return s.save(u.id(),d);}@GetMapping public List<Response> list(@AuthenticationPrincipal CurrentUser u){return s.list(u.id());}@GetMapping("/{id}")public Response get(@AuthenticationPrincipal CurrentUser u,@PathVariable String id){return s.get(u.id(),id);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@AuthenticationPrincipal CurrentUser u,@PathVariable String id){s.delete(u.id(),id);}}
